return $input.all()
  .filter(i => i.json.rowType === 'change')
  .map(i => ({ json: {
    detected_at: i.json.detectedAt,
    domain: i.json.domain,
    change: i.json.changeType,
    url: i.json.url,
    lastmod: i.json.lastmod || '',
  }}));

// One Slack message per run: new / removed product pages per competitor.
const SHOW = 8;
const rows = $input.all().map(i => i.json);
const changes = rows.filter(r => r.rowType === 'change');
const summaries = rows.filter(r => r.rowType !== 'change');
if (changes.length === 0) return [];
const esc = s => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const byDomain = {};
for (const c of changes) (byDomain[c.domain] = byDomain[c.domain] || []).push(c);
let text = `*Competitor sitemap changes*: ${changes.length} page(s) on ${Object.keys(byDomain).length} site(s)\n`;
for (const [domain, list] of Object.entries(byDomain)) {
  const n = t => list.filter(c => c.changeType === t).length;
  text += `\n*${domain}*: ${n('new')} new, ${n('removed')} removed, ${n('updated')} updated\n`;
  for (const c of list.filter(c => c.changeType !== 'updated').slice(0, SHOW)) {
    text += `${c.changeType === 'new' ? '+' : '-'} <${c.url}|${esc(c.url.split('/').filter(Boolean).pop())}>\n`;
  }
  if (list.length > SHOW) text += `...and ${list.length - SHOW} more (see the sheet)\n`;
}
const partial = summaries.filter(s => s.status && s.status !== 'ok').map(s => `${s.domain}: ${s.status}`);
if (partial.length) text += `\n_Not fully checked: ${partial.join(', ')}_`;
return [{ json: { text } }];
